import{_ as d,C as e,c,o as i,aa as n,G as t}from"./chunks/framework.ByRpVre_.js";const x=JSON.parse('{"title":"问题排除","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"TownyAdvanced","link":"/wiki/TownyAdvanced"},{"title":"support","link":"/wiki/TownyAdvanced/support"},{"title":"问题排除","link":"/wiki/TownyAdvanced/support/troubleshooting"}]},"headers":[],"relativePath":"wiki/TownyAdvanced/support/troubleshooting.md","filePath":"wiki/TownyAdvanced/support/troubleshooting.md"}'),r={name:"wiki/TownyAdvanced/support/troubleshooting.md"};function s(p,o,u,w,h,b){const a=e("NolebaseGitContributors"),l=e("NolebaseGitChangelog");return i(),c("div",null,[o[0]||(o[0]=n('<h1 id="问题排除" tabindex="-1">问题排除 <a class="header-anchor" href="#问题排除" aria-label="Permalink to &quot;问题排除&quot;">​</a></h1><p>这个页面列出了几种常见问题和解决办法。</p><ul><li>管理员可解决的问题 <ul><li>Towny 锁定在安全模式</li><li>聊天栏有多个前缀叠加</li></ul></li><li>玩家可解决的问题 <ul><li>居民可在其他城镇建筑/破坏</li></ul></li></ul><h2 id="管理员可解决的问题" tabindex="-1">管理员可解决的问题 <a class="header-anchor" href="#管理员可解决的问题" aria-label="Permalink to &quot;管理员可解决的问题&quot;">​</a></h2><h3 id="towny-锁定在安全模式" tabindex="-1">Towny 锁定在安全模式 <a class="header-anchor" href="#towny-锁定在安全模式" aria-label="Permalink to &quot;Towny 锁定在安全模式&quot;">​</a></h3><p>启动服务器之后你可能会遇到无法移动并被强制传送回出生点的情况。这一般是 Towny 进入了安全模式。这个模式会在 Towny 的数据（文件或数据库）遭到损坏时启用，应当予以修复。为了防止数据进一步改动，常见会强制锁定玩家的位置。</p><p>修复数据有两种方法。</p><h4 id="方法一" tabindex="-1">方法一 <a class="header-anchor" href="#方法一" aria-label="Permalink to &quot;方法一&quot;">​</a></h4><p>相对简单的恢复方式就是插件自带的备份功能。每次服务器启动与城镇日过后均会自动创建一份。不过它只会在你以文件数据库的形式保存数据时有效。</p><ol><li>关闭服务器；</li><li>打开 <code>plugins\\towny</code> 文件夹；</li><li>找到 <code>data</code> 文件夹，修改其名称，如果问题解决，你可以随后删除这个文件夹；</li><li>打开 <code>backup</code> 文件夹；</li><li>选择最新或较新的归档，并用压缩软件打开它；</li><li>将里面的 <code>data</code> 文件夹解压到 <code>plugins\\towny</code> 中；</li><li>启动服务器，并检查日志关于 Towny 的部分。如果插件仍然触发了安全模式，选择时间更早的备份并重做第三步。</li></ol><h4 id="方法二" tabindex="-1">方法二 <a class="header-anchor" href="#方法二" aria-label="Permalink to &quot;方法二&quot;">​</a></h4><p>需要你有一定的操作经验。只建议在极端情况（如备份数据过老或不存在）时手动编辑 Towny 的数据。</p><ol><li>关闭服务器；</li><li>打开 <code>plugins\\towny</code> 文件夹；</li><li>将 <code>data</code> 文件夹复制到其他安全的地方，修改其名称备用；</li><li>在 <code>config.yml</code> 中设置 <code>debug_mode: true</code>；</li><li>再次开启服务器，在服务器的日志中找到有关 Towny 的部分内容。</li></ol><p><strong>注意：下方的教程只适用于低于 0.96.3.0 的版本。</strong></p><blockquote><p>大于此版本的 Towny 对城镇与国家、居民与城镇间的关系进行了调整，使其分离存储。这样插件就可以更精确地保护损坏的数据。如果你正在使用旧版的 Towny，如下教程可以帮助你解决安全模式问题。</p></blockquote><p>数据出错可能有四种类型。通常情况下是某个文件在其他文件中未找到。例如：<code>城镇名称.txt</code> 中存在一个 <code>residents.txt</code> 中没有的成员，或者 <code>世界名称.txt</code> 列出了一个不存在于 <code>城镇.txt</code> 中的城镇。</p><p>世界：世界列表在 <code>worlds.txt</code> 中显示，且分别有 <code>世界名称.txt</code> 文件。Towny 在其中找到了无效的世界名称，但列表中的所有城镇都在 <code>towns.txt</code> 中，此时它不会载入数据。如果列表中出现了额外城镇，那么你就需要视情况决定接下来做的事：</p><blockquote><p>如果 <code>towns.txt</code> 没有这个城镇，但对应城镇的 txt 文件却存在于 <code>towny\\data\\towns</code>，将这个城镇的名称添加进 <code>towns.txt</code> 文件即可。</p></blockquote><blockquote><p>如果 <code>towns.txt</code> 没有这个城镇，且 <code>towny\\data\\towns</code> 也没有对应的文件，将这个城镇从 <code>世界名称.txt</code> 文件中删除即可。</p></blockquote><p>国家：国家数据文件损坏通常是无效城镇引起的。打开 towny\\data\\nations 文件夹下的 国家名称.txt 文件，查看里面是否列出了不存在的城镇，确保所有城镇的名字都出现在 towny\\data 文件夹中。如果出现了额外城镇，那么你就需要视情况决定接下来做的事：</p><blockquote><p>如果 <code>towns.txt</code> 没有这个城镇，但对应城镇的 txt 文件却存在于 <code>towny\\data\\towns</code>，将这个城镇的名称添加进 <code>towns.txt</code> 文件即可。</p></blockquote><blockquote><p>如果 <code>towns.txt</code> 没有这个城镇，且 <code>towny\\data\\towns</code> 也没有对应的文件，将这个城镇从 <code>世界名称.txt</code> 文件中删除即可。</p></blockquote><p>城镇：城镇数据文件损坏通常是无效居民引起的。打开 towny\\data\\towns 文件夹下的 城镇名称.txt 文件，查看里面是否列出了不存在的玩家，确保所有玩家的名字都出现在 towny\\data 文件夹中。如果出现了额外玩家，那么你就需要视情况决定接下来做的事：</p><blockquote><p>如果 <code>residents.txt</code> 没有这个玩家，但对应玩家的 txt 文件却存在于 <code>towny\\data\\residents</code>，将这个玩家的名称添加进 <code>城镇名称.txt</code> 文件即可。</p></blockquote><blockquote><p>如果 <code>towns.txt</code> 没有这个玩家，且 <code>towny\\data\\residents</code> 也没有对应的文件，将这个玩家从 <code>城镇名称.txt</code> 文件中删除即可。</p></blockquote><p>居民：无效居民通常是 residents.txt 中的玩家没有在 towny\\data\\residents 文件夹下对应的 居民名称.txt 导致的，大部分情况下，只需删除 residents.txt 中的名称即可。</p><p>手动编辑数据之后，查看启动后控制台的 Towny 部分消息，确认数据是否成功修复。插件可能会列出新发现的损坏数据。此时只需按上述步骤重做即可。</p><h3 id="聊天栏有多个前缀叠加" tabindex="-1">聊天栏有多个前缀叠加 <a class="header-anchor" href="#聊天栏有多个前缀叠加" aria-label="Permalink to &quot;聊天栏有多个前缀叠加&quot;">​</a></h3><p>如果你发现你的聊天栏出现了这种情况：</p><p><code>[拥有者]拥有者[拥有者] 玩家名称</code>，带有两个额外的前缀，那么你需要修改 chatconfig.yml。</p><p>出现问题的聊天变量可能是这三个。</p><ol><li>{group}，即权限插件的权限组名称</li><li>{permprefix}，即权限插件的前缀部分</li><li>{modplayername}，会包含其他修改聊天的插件前缀</li></ol><p>你可以这样做：</p><ol><li>在 <code>\\towny\\settings\\chatconfig.yml</code></li></ol><ul><li>找到 <code>channel_formats:</code> 和 <code>global:</code>部分；</li><li>将 {modplayername} 改成 {playername}；</li><li>删掉 {groups}。</li></ul><ol start="2"><li>在游戏内输入 <code>/townychat reload</code>。问题应该就可以解决。</li></ol><p>照做之后就可以让 townychat 只使用 {permprefix} 聊天标签，排除了权限插件显示的颜色与聊天前缀。</p><h2 id="玩家可以解决的问题" tabindex="-1">玩家可以解决的问题 <a class="header-anchor" href="#玩家可以解决的问题" aria-label="Permalink to &quot;玩家可以解决的问题&quot;">​</a></h2><h3 id="居民可在其他城镇建筑-破坏" tabindex="-1">居民可在其他城镇建筑/破坏 <a class="header-anchor" href="#居民可在其他城镇建筑-破坏" aria-label="Permalink to &quot;居民可在其他城镇建筑/破坏&quot;">​</a></h3><p>如果城镇拥有者发现他的居民可以在其他城镇中破坏建造，但是他只需要将这些行为限制在他们的地皮中，那么可以这样做：</p><ol><li>输入命令 <code>/town set perm off</code></li><li>输入命令 <code>/town set perm reset</code></li></ol><p>第一个命令会禁用城镇内所有居民/盟友/访客的权限。第二个命令会将新改变的默认权限设置为所有城镇地皮。这两条命令均不会影响城镇拥有者的地皮。</p>',42)),t(a),t(l)])}const k=d(r,[["render",s]]);export{x as __pageData,k as default};
